def largest_prime_factor(n: int) -> int:
    if n <= 0:
        raise ValueError("Input must be a positive integer")

    # Check for factor 2
    if n % 2 == 0:
        return n // 2

    # Check odd factors starting from 3
    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    # If no factors found, n is prime
    return n
